#!/usr/bin/python3
from __future__ import print_function
import json
import os
from http.server import BaseHTTPRequestHandler, HTTPServer

APP_DIR = os.path.dirname(os.path.abspath(__file__))
DATA_FILE = os.path.join(APP_DIR, 'inventory.json')

class InventoryHandler(BaseHTTPRequestHandler):
    server_version = 'InventoryHTTP/1.0'

    def _send_json(self, status, payload, body=True):
        encoded = json.dumps(payload, sort_keys=True, indent=2).encode('utf-8') + b'\n'
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(encoded)))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        if body:
            self.wfile.write(encoded)

    def do_GET(self):
        if self.path == '/health':
            self._send_json(200, {'service': 'inventory', 'status': 'ok'})
            return
        if self.path in ('/', '/inventory'):
            try:
                with open(DATA_FILE, 'r') as inventory_file:
                    inventory = json.load(inventory_file)
                self._send_json(200, inventory)
            except (IOError, ValueError) as error:
                self._send_json(500, {'status': 'error', 'detail': str(error)})
            return
        self._send_json(404, {'status': 'not found'})

    def do_HEAD(self):
        if self.path == '/health':
            self._send_json(200, {'service': 'inventory', 'status': 'ok'}, False)
        elif self.path in ('/', '/inventory'):
            self._send_json(200, {'service': 'inventory'}, False)
        else:
            self._send_json(404, {'status': 'not found'}, False)

    def log_message(self, message_format, *args):
        print('%s - - [%s] %s' % (self.client_address[0], self.log_date_time_string(), message_format % args), flush=True)

if __name__ == '__main__':
    bind_address = os.environ.get('INVENTORY_BIND', '0.0.0.0')
    port = int(os.environ.get('INVENTORY_PORT', '8181'))
    server = HTTPServer((bind_address, port), InventoryHandler)
    print('inventory service listening on %s:%d' % (bind_address, port), flush=True)
    server.serve_forever()
